from pathlib import Path
import json,argparse
from compare_answers import comparison_policy
HERE=Path(__file__).resolve().parent

def build():
 spec=json.loads((HERE.parent/'task/data/model_spec.json').read_text());ref=json.loads((HERE/'final_answer.json').read_text())
 weights={'course_decision':40,'counterfactual_predictions':25,'global_identifiability':20,'continuous_peak_witness':10,'measurement_fit':5}
 r={'full_grading_command':'python expert_solution/verify_submission.py --solver PATH --data task/data --output-dir OUTPUT --replay-control','case_id':spec['case_id'],'weights':weights,'pass_threshold':80,'scientific_failure_cap':79,'presentation_deduction':5,'delivery_deductions':{'analysis_diagnostics':5,'summary_hashes':5,'total_cap':10},'execution_gate':'Submitted pipeline must execute in staged offline isolation and pass both base and physically regenerated data. A failed or non-running pipeline or failed regenerated scientific result prevents acceptance and caps overall score at 79; missing/non-running pipeline is zero.','requirements_rule':'requirements.txt must exist and list numpy, scipy and jsonschema if imported by submitted code; missing/incorrect declaration deducts 2, within delivery cap 10.','automatic_zero':['absent/unreadable/duplicate-key/nonfinite JSON','missing or non-running pipeline in full submission verification'],'tolerances':spec['acceptance'],'dimensions':{'chips':len(ref['chips']),'courses':len(ref['courses']),'model_counts':{c['id']:len(c['models']) for c in ref['chips']}},'field_contract':{'course_decision':'prompt.md: Counterfactual courses','counterfactual_predictions':'prompt.md: Counterfactual courses','global_identifiability':'prompt.md: Measurements and inference target','continuous_peak_witness':'prompt.md: Counterfactual courses','measurement_fit':'prompt.md: Measurements and inference target','delivery':'prompt.md: Diagnostic evidence and Required deliverables'},'ordering':'IDs and model-equivalence mappings; all array orderings accepted with consistent model indices','caps':'Any failed scientific group caps at 79; execution/input-dependence failure caps at 79; caps precede presentation and delivery deductions. Pass threshold 80 inclusive. Group credit is all-or-nothing. Presentation deduction applies once and never activates a scientific cap. Delivery deductions total at most 10 including requirements.','recovery':'One-element answer-array wrapper and numeric strings are normalized before scientific evaluation. Extra fields and schema/case metadata slips incur presentation only. No arbitrary identifier renaming is accepted.','ground_truth':'Computed canonical inverse solution, verified against independent integration and generation truth; no typed answer values in rubric.'}
 r['numeric_tolerance']=1e-8
 r['numeric_tolerance_scope']='Legacy oracle execution fallback only; scientific solver grading uses the unchanged public thresholds in tolerances and model_spec.json.'
 r['oracle_comparison']=comparison_policy(spec['acceptance'])
 text='# Rubric\n\nFull submitted-code grading: `'+r['full_grading_command']+'`.\n\n'+ '\n'.join(f'* {k}: {v} points; all published fields in that group must pass.' for k,v in weights.items())+'\n\n'+r['caps']+'\n\n'+r['execution_gate']+'\n\n'+r['requirements_rule']+'\n\nAutomatic zeros: '+ '; '.join(r['automatic_zero'])+'.\n\nRecovery: '+r['recovery']+'\n\nDelivery deductions: analysis diagnostic block 5; summary hashes/schema 5; requirements 2; combined cap 10.\n\n## Public tolerances and data-derived dimensions\n\n```json\n'+json.dumps({'tolerances':r['tolerances'],'dimensions':r['dimensions'],'field_contract':r['field_contract']},indent=2)+'\n```\n\n## Oracle execution comparison\n\nThe legacy numeric fallback is 1e-8; it does not replace any scientific acceptance rule. Oracle comparison uses the explicit paths and semantic witness checks below. Serialization precision applies only to oracle execution reproducibility, never to solver grading.\n\n```json\n'+json.dumps(r['oracle_comparison'],indent=2)+'\n```\n'
 return json.dumps(r,indent=2)+'\n',text
if __name__=='__main__':
 p=argparse.ArgumentParser();p.add_argument('--check',action='store_true');a=p.parse_args()
 for name,text in zip(['rubric.json','rubric.md'],build()):
  path=HERE/name
  if a.check:assert path.read_text()==text,'rubric drift: '+name
  else:path.write_text(text)
